#!/usr/bin/env node
/**
 * CLI von @compdata/cms
 *
 *   cms init [verzeichnis] [--name <paketname>]   Kundenprojekt anlegen (Gerüst + Stubs)
 *   cms sync [--force]                            Stubs (Routen, Hooks) auf den Paketstand bringen
 *   cms check                                     Stubs prüfen, geänderte Dateien melden
 *   cms postinstall                               intern: sync nach npm install/update
 *
 * Stubs sind generierte Dateien ohne eigene Logik (Header „@generated"). Ein Manifest
 * unter .cms/manifest.json merkt sich ihre Prüfsummen: Nur unveränderte Stubs werden
 * bei Updates ersetzt oder entfernt, vom Kunden geänderte Dateien bleiben stehen und
 * werden gemeldet. Projektdateien (Vorlagen unter templates/project) legt nur `init`
 * an und fasst sie nie wieder an.
 */
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const PKG_DIR = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const PKG = JSON.parse(readFileSync(join(PKG_DIR, 'package.json'), 'utf8'));
const TEMPLATES = join(PKG_DIR, 'templates');
const MANIFEST = '.cms/manifest.json';

const args = process.argv.slice(2);
const cmd = args[0];
const flags = new Set(args.filter((a) => a.startsWith('--')));
const positional = args.slice(1).filter((a) => !a.startsWith('--'));
const flagValue = (name) => {
	const i = args.indexOf(name);
	return i >= 0 ? args[i + 1] : undefined;
};
const quiet = flags.has('--quiet');
const log = (...m) => {
	if (!quiet) console.log(...m);
};

function walk(dir, base = dir) {
	const out = [];
	for (const entry of readdirSync(dir, { withFileTypes: true })) {
		const full = join(dir, entry.name);
		if (entry.isDirectory()) out.push(...walk(full, base));
		else out.push(relative(base, full).split(sep).join('/'));
	}
	return out.sort();
}

const sha1 = (s) => createHash('sha1').update(s).digest('hex');

function header(file) {
	const note = `@generated by @compdata/cms ${PKG.version} — nicht bearbeiten, wird bei Updates ersetzt (npx cms sync)`;
	if (file.endsWith('.svelte')) return `<!-- ${note} -->\n`;
	return `// ${note}\n`;
}

function readManifest(root) {
	try {
		return JSON.parse(readFileSync(join(root, MANIFEST), 'utf8'));
	} catch {
		return { version: null, files: {} };
	}
}

function writeManifest(root, manifest) {
	mkdirSync(join(root, '.cms'), { recursive: true });
	writeFileSync(join(root, MANIFEST), JSON.stringify(manifest, null, '\t') + '\n');
}

function isProject(root) {
	return existsSync(join(root, 'src', 'cms.config.ts')) || existsSync(join(root, MANIFEST));
}

/** Stubs schreiben. Liefert Zusammenfassung. */
function sync(root, { force = false } = {}) {
	const stubsDir = join(TEMPLATES, 'stubs');
	const manifest = readManifest(root);
	const next = { version: PKG.version, files: {} };
	const result = { written: [], skipped: [], removed: [], unchanged: [] };

	for (const rel of walk(stubsDir)) {
		const content = header(rel) + readFileSync(join(stubsDir, rel), 'utf8');
		const hash = sha1(content);
		const target = join(root, rel);
		next.files[rel] = hash;
		if (existsSync(target)) {
			const current = readFileSync(target, 'utf8');
			if (sha1(current) === hash) {
				result.unchanged.push(rel);
				continue;
			}
			const known = manifest.files[rel];
			const customerModified = known && sha1(current) !== known;
			const unknownForeign = !known && !current.includes('@generated by @compdata/cms');
			if ((customerModified || unknownForeign) && !force) {
				result.skipped.push(rel);
				next.files[rel] = sha1(current); // Kundenstand merken, damit er nicht erneut gemeldet wird
				continue;
			}
		}
		mkdirSync(dirname(target), { recursive: true });
		writeFileSync(target, content);
		result.written.push(rel);
	}

	// Stubs, die es im Paket nicht mehr gibt: nur entfernen, wenn unverändert.
	for (const [rel, hash] of Object.entries(manifest.files)) {
		if (next.files[rel]) continue;
		const target = join(root, rel);
		if (!existsSync(target)) continue;
		if (sha1(readFileSync(target, 'utf8')) === hash || force) {
			rmSync(target);
			result.removed.push(rel);
			let dir = dirname(target);
			while (dir !== root && readdirSync(dir).length === 0) {
				rmSync(dir, { recursive: true });
				dir = dirname(dir);
			}
		} else {
			result.skipped.push(rel);
		}
	}

	writeManifest(root, next);
	return result;
}

function report(result, previousVersion) {
	if (previousVersion && previousVersion !== PKG.version) log(`@compdata/cms: Stubs von ${previousVersion} auf ${PKG.version} aktualisiert.`);
	for (const f of result.written) log(`  + ${f}`);
	for (const f of result.removed) log(`  - ${f}`);
	for (const f of result.skipped) console.warn(`  ! ${f} wurde geändert und bleibt stehen — mit \`npx cms sync --force\` ersetzen`);
	if (!result.written.length && !result.removed.length && !result.skipped.length) log('@compdata/cms: Stubs sind aktuell.');
}

function copyProject(root, { name }) {
	const dir = join(TEMPLATES, 'project');
	const created = [];
	for (const rel of walk(dir)) {
		const target = join(root, rel.replace(/^_gitignore$/, '.gitignore').replace(/^_npmrc$/, '.npmrc'));
		if (existsSync(target)) continue;
		let content = readFileSync(join(dir, rel), 'utf8');
		content = content.replaceAll('__PROJECT_NAME__', name).replaceAll('__CMS_VERSION__', PKG.version);
		mkdirSync(dirname(target), { recursive: true });
		writeFileSync(target, content);
		created.push(relative(root, target));
	}
	return created;
}

switch (cmd) {
	case 'init': {
		const root = resolve(positional[0] ?? '.');
		const name = flagValue('--name') ?? root.split(sep).pop().toLowerCase().replace(/[^a-z0-9-]+/g, '-');
		mkdirSync(root, { recursive: true });
		const created = copyProject(root, { name });
		const result = sync(root);
		log(`@compdata/cms ${PKG.version}: Projekt „${name}" in ${root}`);
		for (const f of created) log(`  + ${f}`);
		report(result, null);
		log(`
Nächste Schritte:
  cd ${relative(process.cwd(), root) || '.'}
  cp .env.example .env            # AUTH_SECRET und Mail-Einstellungen setzen
  docker compose -f docker-compose.dev.yml up -d --build
  → http://localhost:5173 und /admin (erster Nutzer wird Admin, ALLOW_SIGNUP=1)
Eigene Inhaltstypen: src/blocks, src/collections, src/mail — siehe AGENTS.md.`);
		break;
	}
	case 'sync': {
		const root = process.cwd();
		if (!isProject(root)) {
			console.error('Kein CMS-Projekt (src/cms.config.ts fehlt). Zuerst: npx cms init');
			process.exit(1);
		}
		const prev = readManifest(root).version;
		report(sync(root, { force: flags.has('--force') }), prev);
		break;
	}
	case 'check': {
		const root = process.cwd();
		const manifest = readManifest(root);
		const stubsDir = join(TEMPLATES, 'stubs');
		let problems = 0;
		if (manifest.version !== PKG.version) {
			console.warn(`Stubs stammen von ${manifest.version ?? 'unbekannt'}, installiert ist ${PKG.version} — npx cms sync ausführen.`);
			problems++;
		}
		for (const rel of walk(stubsDir)) {
			const target = join(root, rel);
			if (!existsSync(target)) {
				console.warn(`fehlt: ${rel}`);
				problems++;
			} else if (manifest.files[rel] && sha1(readFileSync(target, 'utf8')) !== manifest.files[rel]) {
				console.warn(`geändert: ${rel}`);
				problems++;
			}
		}
		console.log(problems ? `${problems} Problem(e).` : 'Alle Stubs aktuell und unverändert.');
		process.exit(problems ? 1 : 0);
		break;
	}
	case 'postinstall': {
		// Nach `npm install`/`npm update` im Kundenprojekt: Stubs still nachziehen.
		const root = process.env.INIT_CWD ? resolve(process.env.INIT_CWD) : null;
		if (!root || resolve(root) === PKG_DIR || !isProject(root)) break;
		const prev = readManifest(root).version;
		const result = sync(root);
		if (result.written.length || result.removed.length || result.skipped.length) report(result, prev);
		break;
	}
	default:
		console.log(`@compdata/cms ${PKG.version}\n\n  cms init [verzeichnis] [--name paketname]\n  cms sync [--force]\n  cms check`);
		process.exit(cmd ? 1 : 0);
}
